package dev.eugheist.tc4modern;
/** ThaumcraftWorldGenerator.generateVegetation + WorldGenCustomFlowers: hot sand, 1/30, eighteen attempts. */
public final class CinderpearlFeature extends net.minecraft.world.level.levelgen.feature.Feature<net.minecraft.world.level.levelgen.feature.configurations.NoneFeatureConfiguration>{
 public CinderpearlFeature(){super(net.minecraft.world.level.levelgen.feature.configurations.NoneFeatureConfiguration.CODEC);}
 @Override public boolean place(net.minecraft.world.level.levelgen.feature.FeaturePlaceContext<net.minecraft.world.level.levelgen.feature.configurations.NoneFeatureConfiguration> c){if(!WorldgenConfig.trees())return false;var level=c.level();var random=c.random();var p=c.origin();p=level.getHeightmapPos(net.minecraft.world.level.levelgen.Heightmap.Types.WORLD_SURFACE_WG,p);if(p.getY()>=level.getMaxBuildHeight()||level.getBiome(p).value().getBaseTemperature()<=1||!level.getBlockState(p.below()).is(net.minecraft.world.level.block.Blocks.SAND)||random.nextInt(30)!=0)return false;boolean placed=false;for(int i=0;i<18;i++){var at=p.offset(random.nextInt(8)-random.nextInt(8),random.nextInt(4)-random.nextInt(4),random.nextInt(8)-random.nextInt(8));var below=level.getBlockState(at.below());if(level.isEmptyBlock(at)&&(below.is(net.minecraft.world.level.block.Blocks.GRASS_BLOCK)||below.is(net.minecraft.world.level.block.Blocks.SAND))){level.setBlock(at,BasicsContent.CINDERPEARL.get().defaultBlockState(),3);placed=true;}}return placed;}
}
